### What problem does a dead-letter queue solve?

The core problem is the poison pill: a single record that always fails to process. Without a DLQ, a naive consumer that retries forever blocks the partition, and one that skips it loses the data silently. The DLQ gives a safe third option: move the bad record aside and continue.

```java
package com.bank.kafka;

public class PoisonPillProblem {
    public static void main(String[] args) {
        System.out.println("Without DLQ:");
        System.out.println("  Retry forever -> partition blocked, lag grows");
        System.out.println("  Skip silently -> data lost, no visibility");
        System.out.println();
        System.out.println("With DLQ:");
        System.out.println("  Move bad record to DLQ -> partition advances, data preserved");
        System.out.println("  Supervisor inspects DLQ -> fix and redrive");
    }
}
```

```text
Expected output:
Without DLQ:
  Retry forever -> partition blocked, lag grows
  Skip silently -> data lost, no visibility

With DLQ:
  Move bad record to DLQ -> partition advances, data preserved
  Supervisor inspects DLQ -> fix and redrive
```

### How do you implement a DLQ consumer?

The consumer disables auto-commit, processes each record, retries transient failures, and on permanent failure or retry exhaustion sends to the DLQ topic, then commits.

```java
package com.bank.kafka;

import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.header.internals.RecordHeader;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.apache.kafka.common.serialization.StringSerializer;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.Collections;
import java.util.Properties;

public class DlqConsumer {
    private static final String SOURCE_TOPIC = "transfers";
    private static final String DLQ_TOPIC = "transfers.DLT";
    private static final int MAX_RETRIES = 3;

    public static void main(String[] args) {
        // Consumer config
        Properties consumerProps = new Properties();
        consumerProps.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "kafka-1:9092");
        consumerProps.put(ConsumerConfig.GROUP_ID_CONFIG, "settlement-service");
        consumerProps.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        consumerProps.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        consumerProps.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "false");
        consumerProps.put(ConsumerConfig.MAX_POLL_RECORDS_CONFIG, "50");

        // DLQ producer config
        Properties producerProps = new Properties();
        producerProps.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "kafka-1:9092");
        producerProps.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        producerProps.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        producerProps.put(ProducerConfig.ACKS_CONFIG, "all");
        producerProps.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "true");

        try (KafkaConsumer<String, String> consumer = new KafkaConsumer<>(consumerProps);
             KafkaProducer<String, String> dlqProducer = new KafkaProducer<>(producerProps)) {

            consumer.subscribe(Collections.singletonList(SOURCE_TOPIC));

            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(500));
                for (ConsumerRecord<String, String> record : records) {
                    try {
                        processTransfer(record);
                    } catch (PermanentFailureException e) {
                        sendToDlq(dlqProducer, record, e, 0);
                    } catch (Exception e) {
                        handleWithRetry(dlqProducer, record, e);
                    }
                }
                if (!records.isEmpty()) {
                    consumer.commitSync();
                }
            }
        }
    }

    private static void processTransfer(ConsumerRecord<String, String> record) {
        // Parse and validate the transfer
        System.out.println("Processing: " + record.key() + " -> " + record.value());
        if (record.value() == null || record.value().isEmpty()) {
            throw new PermanentFailureException("Empty transfer payload");
        }
        // Apply to ledger...
    }

    private static void handleWithRetry(
            KafkaProducer<String, String> dlqProducer,
            ConsumerRecord<String, String> record, Exception e) {
        for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
            try {
                Thread.sleep(attempt * 1000L); // Backoff
                processTransfer(record);
                return; // Retry succeeded
            } catch (Exception retryEx) {
                System.out.println("Retry " + attempt + "/" + MAX_RETRIES + " failed");
            }
        }
        sendToDlq(dlqProducer, record, e, MAX_RETRIES);
    }

    private static void sendToDlq(
            KafkaProducer<String, String> dlqProducer,
            ConsumerRecord<String, String> record, Exception e, int attempts) {
        ProducerRecord<String, String> dlqRecord =
            new ProducerRecord<>(DLQ_TOPIC, record.key(), record.value());

        // Add failure metadata as headers
        dlqRecord.headers().add(new RecordHeader("original-topic",
            SOURCE_TOPIC.getBytes(StandardCharsets.UTF_8)));
        dlqRecord.headers().add(new RecordHeader("original-partition",
            String.valueOf(record.partition()).getBytes(StandardCharsets.UTF_8)));
        dlqRecord.headers().add(new RecordHeader("original-offset",
            String.valueOf(record.offset()).getBytes(StandardCharsets.UTF_8)));
        dlqRecord.headers().add(new RecordHeader("exception-class",
            e.getClass().getName().getBytes(StandardCharsets.UTF_8)));
        dlqRecord.headers().add(new RecordHeader("exception-message",
            e.getMessage().getBytes(StandardCharsets.UTF_8)));
        dlqRecord.headers().add(new RecordHeader("retry-attempts",
            String.valueOf(attempts).getBytes(StandardCharsets.UTF_8)));

        try {
            dlqProducer.send(dlqRecord).get(); // Wait for ack
            System.out.println("Sent to DLQ: " + record.key() + " reason: " + e.getMessage());
        } catch (Exception dlqEx) {
            // If DLQ write fails, do NOT commit -- record will be retried
            throw new RuntimeException("DLQ write failed", dlqEx);
        }
    }
}

class PermanentFailureException extends RuntimeException {
    public PermanentFailureException(String message) { super(message); }
}
```

